import json

def main(topic_item):
    if isinstance(topic_item, str):
        try:
            topic_item = json.loads(topic_item)
        except Exception:
            topic_item = {}
    if not isinstance(topic_item, dict):
        topic_item = {}

    pages = topic_item.get('top_cited_pages') or []
    urls, titles = [], []
    for p in pages[:3]:
        u = (p.get('url') or '').strip()
        if not u:
            continue
        if not u.startswith('http'):
            u = 'https://' + u.lstrip('/')
        urls.append(u)
        titles.append(p.get('title') or '')

    # Guard: scrape node fails on an empty URL, so fall back to the
    # competitor homepage rather than passing an empty string.
    comp = topic_item.get('competitor', '')
    fallback = {
        'Competitor A': 'https://competitor-a.example/',
        'Competitor B': 'https://competitor-b.example/',
        'Competitor C': 'https://competitor-c.example/',
        'Competitor D': 'https://competitor-d.example/',
        'Competitor E': 'https://competitor-e.example/'
    }.get(comp, 'https://example.com/')

    def pick(i):
        return urls[i] if len(urls) > i else (urls[0] if urls else fallback)

    others = topic_item.get('all_competitors') or []
    context_lines = []
    for c in others:
        context_lines.append(f"{c.get('competitor','')}: {c.get('comp_score',0):.2f}pp (change {c.get('comp_delta',0):+.2f}pp)")

    return {
        'url1': pick(0),
        'url2': pick(1),
        'url3': pick(2),
        'page_titles': ' | '.join(t for t in titles if t) or '(no page titles available)',
        'had_real_pages': bool(urls),
        'topic': topic_item.get('topic', ''),
        'competitor': comp,
        'comp_score': float(topic_item.get('comp_score', 0) or 0),
        'brand_score': float(topic_item.get('brand_score', 0) or 0),
        'comp_delta': float(topic_item.get('comp_delta', 0) or 0),
        'brand_delta': float(topic_item.get('brand_delta', 0) or 0),
        'gap_pp': float(topic_item.get('gap_pp', 0) or 0),
        'competitor_context': '\n'.join(context_lines) or '(no other competitor data)'
    }

