from collections import defaultdict

DOMAIN_MAP = {
    'Competitor A': 'competitor-a.example',
    'Competitor B': 'competitor-b.example',
    'Competitor C': 'competitor-c.example',
    'Competitor D': 'competitor-d.example',
    'Competitor E': 'competitor-e.example'
}

def build_index(citation_pages):
    """topic -> domain -> [pages]. Domain match is substring-based both ways
    so subdomains and root-domain rollups both land."""
    idx = defaultdict(lambda: defaultdict(list))
    for r in (citation_pages or []):
        topic = (r.get('topic') or '').strip()
        dom = (r.get('domain') or '').strip().lower()
        url = r.get('url') or r.get('page') or ''
        title = r.get('page_title') or ''
        try:
            cnt = int(float(r.get('metric_value', 0) or 0))
        except (TypeError, ValueError):
            cnt = 0
        if dom and url:
            idx[topic][dom].append({'url': url, 'title': title, 'count': cnt})
    for t in idx:
        for d in idx[t]:
            idx[t][d].sort(key=lambda x: x['count'], reverse=True)
    return idx

def pages_for(idx, topic, competitor, n):
    target = DOMAIN_MAP.get(competitor, '').lower()
    if not target:
        return []
    root = target.split('.')[0]
    out = []
    # Exact topic scope first
    for dom, pages in idx.get(topic, {}).items():
        if target in dom or dom in target or root in dom:
            out.extend(pages)
    # Do not borrow pages from another topic. Empty evidence is safer than
    # presenting a cross-topic fallback as topic-specific citation evidence.
    # De-duplicate by URL, keeping highest count
    best = {}
    for p in out:
        prev = best.get(p['url'])
        if prev is None or p['count'] > prev['count']:
            best[p['url']] = p
    ranked = sorted(best.values(), key=lambda x: x['count'], reverse=True)
    return ranked[:n]

def main(surpass, closing, citation_pages):
    idx = build_index(citation_pages)

    enriched_surpass = []
    for item in (surpass or []):
        e = dict(item)
        e['top_cited_pages'] = pages_for(idx, item.get('topic',''), item.get('competitor',''), 5)
        enriched_surpass.append(e)

    enriched_closing = []
    for item in (closing or []):
        e = dict(item)
        e['top_cited_pages'] = pages_for(idx, item.get('topic',''), item.get('competitor',''), 5)
        enriched_closing.append(e)

    matched = sum(1 for x in enriched_surpass + enriched_closing if x['top_cited_pages'])
    return {
        'surpass_topics': enriched_surpass,
        'closing_topics': enriched_closing,
        'pages_matched_count': matched
    }

def extract_doc_url(doc_json):
    """Google Docs node output shape is not documented; probe likely keys."""
    if not isinstance(doc_json, dict):
        return ''
    for key in ('webViewLink', 'url', 'link'):
        val = doc_json.get(key)
        if isinstance(val, str) and val.startswith('http'):
            return val
    for key in ('documentId', 'document_id', 'id'):
        val = doc_json.get(key)
        if isinstance(val, str) and val:
            return f'https://docs.google.com/document/d/{val}'
    for nest in ('document', 'data', 'result'):
        inner = doc_json.get(nest)
        if isinstance(inner, dict):
            nested = extract_doc_url(inner)
            if nested:
                return nested
    return ''

def main(topic, competitor, comp_score, brand_score, doc_json):
    doc_url = extract_doc_url(doc_json)
    link_text = doc_url if doc_url else '(brief doc link unavailable)'
    msg = (f'Content brief ready \u2014 {topic}. '
           f'{competitor} is ahead at {float(comp_score):.1f}pp vs Primary Brand at {float(brand_score):.1f}pp. '
           f'Brief to reclaim #1 \u2192 {link_text}')
    return {'message_c': msg}

