def main(surpass, closing, doc_json, week_label):
    url = extract_doc_url(doc_json)
    link = url if url else '(doc link unavailable)'

    n_sur, n_clo = len(surpass or []), len(closing or [])

    # Message A: routine weekly digest
    a = [f'Latest competitor content analysis is ready. {week_label}.']
    a.append(f'{n_sur} surpass | {n_clo} closing gap')
    a.append(f'Full analysis \u2192 {link}')
    message_a = '\n'.join(a)

    # Message B: surpass red flag
    if surpass:
        alerts = []
        for i in surpass:
            alerts.append(
                f"\U0001f6a8 Competitor overlap detected \u2014 {i.get('competitor','')} has surpassed "
                f"Primary Brand on {i.get('topic','')} "
                f"({i.get('competitor','')} {i.get('comp_score',0):.2f}pp vs Primary Brand {i.get('brand_score',0):.2f}pp, "
                f"deficit {i.get('comp_score',0)-i.get('brand_score',0):.2f}pp).\n"
                f"Pages driving this are in the report: {link}"
            )
        message_b = '\n\n'.join(alerts)
    else:
        message_b = f'No competitor surpass events this week. {week_label}.'

    # Closing gap notice \u2014 previously missing entirely
    if closing:
        top = closing[:5]
        lines = [f'\u26a0\ufe0f Closing gap warning \u2014 {n_clo} topic(s) where a competitor is gaining on Primary Brand.']
        for i in top:
            gap = i.get('gap_pp', 0)
            rate = i.get('rate_of_closure', 0)
            wks = f", ~{gap/rate:.0f} wks to parity" if rate > 0 and gap > 0 else ''
            lines.append(
                f"\u2022 {i.get('topic','')}: {i.get('competitor','')} closing at "
                f"{rate:.2f}pp/wk (Primary Brand leads by {gap:.2f}pp{wks})"
            )
        if n_clo > 5:
            lines.append(f'...and {n_clo-5} more in the report.')
        lines.append(f'Detail \u2192 {link}')
        message_closing_notice = '\n'.join(lines)
    else:
        message_closing_notice = 'No closing-gap warnings this week.'

    return {
        'message_a': message_a,
        'message_b': message_b,
        'message_closing_notice': message_closing_notice,
        'has_surpass': bool(surpass),
        'has_closing': bool(closing)
    }

