def main(doc_json, closing_topics):
    url = extract_doc_url(doc_json)
    count = len(closing_topics) if isinstance(closing_topics, list) else 0
    if count == 0:
        msg = 'No closing-gap topics this week \u2014 no recommendations doc generated.'
    else:
        link_text = url if url else '(doc link unavailable)'
        msg = f'Closing gap recommendations ({count} topic(s)) \u2192 {link_text}'
